// Decode the map of include file name to gzip-compressed, base64-encoded include script model JSON
const includeSourceDecode = async (encodedIncludes) => Object.fromEntries(await Promise.all(
    Object.entries(encodedIncludes).map(async ([includeName, encoded]) => {
        // Base64-decode to bytes
        const binary = atob(encoded);
        const bytes = new Uint8Array(binary.length);
        for (let ixByte = 0; ixByte < binary.length; ixByte++) {
            bytes[ixByte] = binary.charCodeAt(ixByte);
        }

        // Inflate and UTF-8 decode - the Web streams APIs work in browsers and Node.js 18+ without a dependency
        const stream = new DecompressionStream('gzip');
        const writer = stream.writable.getWriter();
        writer.write(bytes);
        writer.close();
        // Read with a reader - Safari doesn't implement ReadableStream async iteration ("for await")
        const reader = stream.readable.getReader();
        const decoder = new TextDecoder();
        let text = '';
        for (let result = await reader.read(); !result.done; result = await reader.read()) {
            text += decoder.decode(result.value, {'stream': true});
        }
        return [includeName, text + decoder.decode()];
    })
));


